-- Migración de datos: 30 fundaciones + 4 solicitudes urgentes
-- Ejecutar en: https://supabase.com/dashboard/project/uboswvsijbddwygypkic/sql/new


-- Solicitudes urgentes vinculadas a fundaciones reales
SELECT id, 'Útiles escolares para 60 niños en Ciudad Bolívar', 'money', 'alta', 4500000, 3240000, '2026-06-14', true
FROM fundaciones WHERE nombre = 'Fundación Sentires';

SELECT id, 'Jornada de reforestación: 500 árboles nativos', 'money', 'media', 6000000, 2750000, '2026-06-20', true
FROM fundaciones WHERE nombre = 'Fundación Humedales Bogotá';

SELECT id, 'Ropa de abrigo para 50 adultos mayores', 'clothes', 'alta', 200, 130, '2026-06-13', true
FROM fundaciones WHERE nombre = 'Fundación La Manuelita';

SELECT id, 'Dotación de libros para biblioteca comunitaria', 'books', 'media', 400, 260, '2026-06-17', true
FROM fundaciones WHERE nombre = 'Fundación Fundevi';

-- Verificar resultado
SELECT 'fundaciones' AS tabla, COUNT(*) AS total FROM fundaciones
UNION ALL
SELECT 'solicitudes', COUNT(*) FROM solicitudes;
